import React, { useState } from 'react';
import axios from 'axios';
import './Prediction.css';

export default function Prediction() {
  const [form, setForm] = useState({
    age: 30,
    gender: 'Female',
    bmi: 25,
    hbA1c_level: 5.7,
    blood_glucose_level: 120,
    hypertension: 0,
    heart_disease: 0,
    smoking_history: 'never'
  });
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = e => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (checked ? 1 : 0) : value
    }));
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setLoading(true);
    setError('');
    
    try {
      const res = await axios.post('http://localhost:8000/predict', form);
      setResult(res.data);
    } catch (err) {
      setError('Prediction failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="prediction">
      <h2>Diabetes Risk Prediction</h2>
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Age:</label>
          <input
            type="number"
            name="age"
            value={form.age}
            onChange={handleChange}
            min="0"
            max="120"
            required
          />
        </div>

        {/* Add other form fields similarly */}
        
        <button type="submit" disabled={loading}>
          {loading ? 'Predicting...' : 'Get Prediction'}
        </button>
      </form>

      {error && <div className="error">{error}</div>}

      {result && (
        <div className={`result ${result.prediction ? 'high-risk' : 'low-risk'}`}>
          <h3>Result: {result.interpretation}</h3>
          <p>Probability: {(result.probability * 100).toFixed(1)}%</p>
        </div>
      )}
    </div>
  );
}
